#include "resident/domains/tasks/task_source_projection.hpp"
// 选择布局与冷inspect共用真正marker集合；依赖不得从今日数据或空表猜测。
#include "task_message_return_profile.hpp"
#include "task_message_return_boundary.hpp"
#include <set>
namespace hanmo::resident {
Outcome<Integer> task_message_return_selected_version(const std::vector<std::pair<StableId,StableId>>& modules){std::set<StableId> seen;std::map<StableId,StableId> versions;for(const auto& row:modules){if(!seen.insert(row.first).second)return {false,{},common_failure("DuplicateNativeModuleIdentity",row.first).error};versions[row.first]=row.second;}auto chosen=versions.find(task_message_return_module);if(chosen==versions.end())return {true,0,{}};if(chosen->second!="1")return {false,{},common_failure("UnsupportedTaskMessageReturnVersion").error};for(const auto& pair:std::vector<std::pair<StableId,StableId>>{{"task_message_handoffs","2"},{"task_static_assets","1"},{"family_life","1"}}){auto found=versions.find(pair.first);if(found==versions.end()||found->second!=pair.second)return {false,{},common_failure("TaskMessageReturnOriginalSourcesRequired",pair.first).error};}return {true,1,{}};}
Status validate_task_message_return_layout(const CommonStore& c,const std::vector<std::pair<StableId,StableId>>& modules,const TaskMessageReturnState* state){auto version=task_message_return_selected_version(modules);if(!version.ok)return {false,{},version.error};if(bool(version.value)!=(state!=nullptr)||(state&&state->version!=1))return common_failure("TaskMessageReturnProfileMismatch");if(!state){for(const auto& row:c.state().facts.rows())if(row.second.domain==task_message_return_module||row.second.kind==task_message_return_started_kind||row.second.kind==task_message_return_collected_kind||row.second.kind==task_message_return_interrupted_kind||row.second.kind==task_message_return_delivered_kind||row.second.kind==task_message_return_report_started_kind||row.second.kind==task_message_return_report_interrupted_kind)return common_failure("TaskMessageReturnProfileRequired",row.first);for(const auto& row:c.state().actions.rows())if(row.second.kind=="task_message_return_collect")return common_failure("TaskMessageReturnProfileRequired",row.first);}return common_success();}
// Common头、独立载荷和JSON逐值对应；孤立副本与活动Action另造参数都不能通过导入。
Outcome<bool> emit_task_message_return_fact_payload_fields(ProjectionWriter& w,const TaskMessageReturnState* state,const FactRecord& h){const bool known=h.kind==task_message_return_started_kind||h.kind==task_message_return_collected_kind||h.kind==task_message_return_interrupted_kind||h.kind==task_message_return_report_started_kind||h.kind==task_message_return_report_interrupted_kind||h.kind==task_message_return_delivered_kind;if(!known&&h.domain!=task_message_return_module)return {true,false,{}};if(!state||!known||h.domain!=task_message_return_module)return {false,{},common_failure("TaskMessageReturnFactMismatch",h.id).error};auto status=emit_task_message_return_fact_fields(w,*state,h.id);if(!status.ok)return {false,{},status.error};w.field("kind",h.kind);w.field("domain",h.domain);return {w.status().ok,w.status().ok,w.status().error};}
Status emit_task_message_return_fact_payloads_fields(ProjectionWriter& w,const CommonStore& c,const TaskMessageReturnState* state){std::size_t emitted=0;for(const auto& row:c.state().facts.rows()){const auto& h=row.second;const bool known=h.kind==task_message_return_started_kind||h.kind==task_message_return_collected_kind||h.kind==task_message_return_interrupted_kind||h.kind==task_message_return_report_started_kind||h.kind==task_message_return_report_interrupted_kind||h.kind==task_message_return_delivered_kind;if(!known&&h.domain!=task_message_return_module)continue;if(!state||!known||h.id!=row.first||h.domain!=task_message_return_module)return common_failure("TaskMessageReturnFactMismatch",row.first);auto checked=w.object(row.first,[&](auto&out){auto status=emit_task_message_return_fact_fields(out,*state,row.first);if(!status.ok)return status;out.field("kind",h.kind);out.field("domain",h.domain);return out.status();});if(!checked.ok)return checked;++emitted;}if(state&&emitted!=state->starts.size()+state->collections.size()+state->deliveries.size()+state->report_starts.size()+state->report_interruptions.size())return common_failure("TaskMessageReturnFactCoverageMismatch");return w.status();}
Outcome<BoundaryValue> task_message_return_fact_payloads(const CommonStore& c,const TaskMessageReturnState* state){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto&out){return emit_task_message_return_fact_payloads_fields(out,c,state);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
Outcome<bool> emit_task_message_return_action_payload_fields(ProjectionWriter& w,const TaskMessageReturnState* state,const ActionCoreView& action){if(action.kind!=task_message_return_collect_command)return {true,false,{}};if(!state)return {false,{},common_failure("TaskMessageReturnProfileRequired",action.id).error};const TaskMessageReturnStart* start=nullptr;for(const auto& r:state->starts.rows())if(r.second.action_id==action.id)start=&r.second;if(!start||action.actor_id!=start->carrier_actor_id||action.start_tick!=start->started_tick)return {false,{},common_failure("TaskMessageReturnActionMismatch",action.id).error};auto status=emit_task_message_return_action_fields(w,*state,action.id);return {status.ok,status.ok,status.error};}
Status emit_task_message_return_action_payloads_fields(ProjectionWriter& w,const CommonStore& c,const TaskMessageReturnState* state){for(const auto& row:c.state().actions.rows())if(row.second.kind==task_message_return_collect_command){if(!state)return common_failure("TaskMessageReturnProfileRequired",row.first);auto encoded=w.object(row.first,[&](auto&out){return emit_task_message_return_action_fields(out,*state,row.first);});if(!encoded.ok)return encoded;const TaskMessageReturnStart* start=nullptr;for(const auto& r:state->starts.rows())if(r.second.action_id==row.first)start=&r.second;if(!start||row.second.id!=row.first||row.second.actor_id!=start->carrier_actor_id||row.second.start_tick!=start->started_tick)return common_failure("TaskMessageReturnActionMismatch",row.first);}return w.status();}
Outcome<BoundaryValue> task_message_return_action_payloads(const CommonStore& c,const TaskMessageReturnState* state){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto&out){return emit_task_message_return_action_payloads_fields(out,c,state);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
Status validate_task_message_return_json_payloads(const CommonStore& c,const TaskMessageReturnState* state,const BoundaryValue& value){try{using namespace boundary;auto expected=task_message_return_fact_payloads(c,state);if(!expected.ok)return {false,{},expected.error};for(const auto& row:object(expected.value,"task_message_returns/facts"))if(!compare_boundary(field(field(value,"facts","state"),row.first,"facts"),row.second).exact())return common_failure("TaskMessageReturnFactPayloadMismatch",row.first);auto actions=task_message_return_action_payloads(c,state);if(!actions.ok)return {false,{},actions.error};for(const auto& row:object(actions.value,"task_message_returns/actions"))if(!compare_boundary(field(field(field(value,"actions","state"),row.first,"actions"),"params",row.first),row.second).exact())return common_failure("TaskMessageReturnActionPayloadMismatch",row.first);return common_success();}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}

}
